-- ============================================================================
-- Octv Platform — Seed / demo data (T030)
-- ----------------------------------------------------------------------------
-- One neutral demo program with a live season and a row in every table the demo
-- script touches (§11): two ensembles, ~12 students + guardians, a competition
-- with a PUBLISHED itinerary, costume set + pieces + assignments, an overnight
-- trip with a bus + rooms, a budget skeleton with a few ledger entries, and
-- volunteer shifts.
--
-- Idempotent: fixed UUIDs + `on conflict do nothing` everywhere, so
-- `supabase db reset` (which runs this after migrations) can re-run safely.
--
-- Staff seats are INVITED memberships (user_id null, invited_email set) — no
-- auth.users rows are created, so the seed never depends on the Auth stack.
-- Accept the invite to sign in; `entered_by`/`uploaded_by` stay null meanwhile.
--
-- Times are now()-relative so the dashboard's "next competition" is always
-- upcoming, no matter when the demo is loaded.
-- ============================================================================

-- --- Program + season + ensembles -------------------------------------------
values ('d0000000-0000-4000-8000-000000000001', 'Demo Show Choir', 'demo',
        'Demo High School', 'Springfield', 'IL', 'America/Chicago', 'program',
        '{"packet_parse": true, "digest": true}'::jsonb)
on conflict do nothing;

values ('d0000000-0000-4000-8000-000000000002', 'd0000000-0000-4000-8000-000000000001',
        '2026-27', (current_date - 60), (current_date + 220), true)
on conflict do nothing;

on conflict do nothing;

